// The superPDF AI SDK for JavaScript and TypeScript: every tool as an async function, run in this process through
// the same contracts as the CLI, the MCP server, the local API and the Python package. Types: sdk/index.d.ts
// (generated by scripts/sdk-types.js from the same schemas).
import { readFile, stat } from 'node:fs/promises';
import path from 'node:path';
import { contractByName, runContract } from '../contracts/tools.js';
import { describeTools, invalidInput } from '../contracts/cli.js';
import { classify } from '../contracts/errors.js';
import { createScope } from '../mcp/scope.js';
import { exportDocument } from '../lib/export.js';

/** A tool refused its input or could not finish. `code` is the same as the local API's problem code. */
export class SuperPDFError extends Error {
  constructor(message, { code = 'operation_failed', status = 422, errors, cause } = {}) {
    super(message, cause ? { cause } : undefined);
    this.name = 'SuperPDFError';
    this.code = code;
    this.status = status;
    if (errors) this.errors = errors;
  }
}

// Fields that hold file or folder paths; each call may use only the folders of the paths it is given.
const PATH_FIELDS = ['input', 'inputs', 'output', 'output_folder', 'folder', 'before', 'after'];

/** The nearest folder that exists: the path itself if it is a folder, else its closest existing parent. */
async function existingFolder(target) {
  for (let dir = target; ; dir = path.dirname(dir)) {
    try { if ((await stat(dir)).isDirectory()) return dir; } catch { /* not there yet */ }
    if (path.dirname(dir) === dir) return process.cwd();
  }
}

/** Absolute paths in the input, and the folders the call may use. */
async function resolvePaths(input, allowDirs) {
  const resolved = { ...input };
  const folders = [];
  for (const field of PATH_FIELDS) {
    const value = resolved[field];
    if (typeof value === 'string') resolved[field] = path.resolve(value);
    else if (Array.isArray(value)) resolved[field] = value.map(item => (typeof item === 'string' ? path.resolve(item) : item));
    for (const item of [resolved[field]].flat()) if (typeof item === 'string') folders.push(await existingFolder(item));
  }
  const allowed = allowDirs ? allowDirs.map(dir => path.resolve(dir)) : folders.length ? folders : [process.cwd()];
  return { input: resolved, allowed: [...new Set(allowed)] };
}

/**
 * Run any tool by name with its JSON input, as the MCP server and the local API do.
 * @param {string} name A tool name such as `pdf_merge` (`tools()` lists them).
 * @param {object} input The tool's input; relative paths are resolved against the current folder.
 * @param {{allowDirs?: string[], onProgress?: (done: number, total: number, message: string) => void}} [options]
 *   `allowDirs` replaces the folders the call may use (by default, the folders of the paths in `input`).
 */
export async function runTool(name, input = {}, { allowDirs, onProgress } = {}) {
  const contract = contractByName.get(name);
  if (!contract) throw new SuperPDFError(`There's no tool called ${name}. tools() lists them.`, { code: 'not_found', status: 404 });
  const parsed = contract.input.safeParse(input);
  if (!parsed.success) {
    const { detail, errors } = invalidInput(contract, parsed.error);
    throw new SuperPDFError(detail, { code: 'validation', errors });
  }
  const { input: resolved, allowed } = await resolvePaths(parsed.data, allowDirs);
  try {
    const scope = await createScope(allowed);
    const { value } = await runContract(contract, resolved, { scope, progress: onProgress });
    return value;
  } catch (error) {
    const { code, status, detail, errors } = classify(error);
    throw new SuperPDFError(detail, { code, status, errors, cause: error });
  }
}

/** Every tool with its name, title, description, MCP annotations and JSON input schema. */
export function tools() {
  return describeTools();
}

const tool = name => (input, options) => runTool(name, input, options);

