/** The PDF's bytes from a path, Buffer or Uint8Array. */
async function pdfBytes(source) {
  if (source instanceof Uint8Array) return source;
  try {
    return new Uint8Array(await readFile(source));
  } catch (error) {
    if (error.code === 'ENOENT') throw new SuperPDFError(`No file at ${source}.`, { code: 'validation', cause: error });
    throw new SuperPDFError(error.message, { cause: error });
  }
}

/**
 * Read a PDF into Markdown, HTML or JSON text, with headings, tables, charts as data and OCR for scanned pages:
 * the same as `superpdf export`.
 * @param {string | Uint8Array} source A path, or the PDF's bytes.
 * @param {{format?: 'markdown'|'html'|'json', pages?: string, tables?: 'markdown'|'html', ocr?: boolean,
 *   onMessage?: (text: string) => void}} [options]
 */
export async function exportPdf(source, { format = 'markdown', pages, tables = 'markdown', ocr = true, onMessage } = {}) {
  const bytes = await pdfBytes(source);
  try {
    return (await exportDocument(bytes, { format, pages, tables, ocr, onMessage })).content;
  } catch (error) {
    throw new SuperPDFError(error.message, { cause: error });
  }
}

/** The document's structure as an object: title, pages with their blocks, and sections. */
export async function exportJson(source, options = {}) {
  return JSON.parse(await exportPdf(source, { ...options, format: 'json' }));
}

const PAGE_END = /^<!-- end of page (\d+) -->\s*$/gm;

/** Markdown per page: `[{ page: 1, markdown: "…" }, …]`, pages counted from 1. */
export async function exportPages(source, options = {}) {
  const text = await exportPdf(source, { ...options, format: 'markdown' });
  const pages = [];
  let start = 0;
  for (const match of text.matchAll(PAGE_END)) {
    pages.push({ page: Number(match[1]), markdown: text.slice(start, match.index).trim() });
    start = match.index + match[0].length;
  }
  return pages;
}
